<section class="section page-top"><div class="container portal-layout"><?php require ROOT_PATH.'/app/Views/admin/_nav.php'; ?><div><h1><?= e($title) ?></h1><?php if(!$rows): ?><div class="panel">Belum ada data.</div><?php else: ?><div class="table-wrap"><table><tr><?php foreach(array_keys($rows[0]) as $h): ?><th><?= e(str_replace('_',' ',ucwords($h))) ?></th><?php endforeach; ?></tr><?php foreach($rows as $r): ?><tr><?php foreach($r as $v): ?><td><?= is_numeric($v)&&str_contains((string)$v,'.')?e($v):e($v) ?></td><?php endforeach; ?></tr><?php endforeach; ?></table></div><?php endif; ?></div></div></section>